package cn.zj.zjmarket.infrastructure.adapter.repository;
import cn.zj.zjmarket.domain.order.adapter.repository.*;
import cn.zj.zjmarket.domain.order.model.entity.MarketOrder;
import cn.zj.zjmarket.domain.order.model.valobj.TradeLease;
import cn.zj.zjmarket.domain.order.service.impl.OrderService;
import cn.zj.zjmarket.domain.payment.adapter.repository.ISettlementRepository;
import cn.zj.zjmarket.domain.payment.adapter.port.IChannelClosing;
import cn.zj.zjmarket.domain.payment.model.valobj.*;
import cn.zj.zjmarket.domain.payment.service.impl.PaymentService;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.*;
import javax.sql.DataSource;
import java.util.*;
import java.nio.charset.StandardCharsets;

/** Mclose -> independent root arbitration -> immutable A declaration. Never releases stock. */
public final class PaymentClosingRepository implements IPaymentClosing {
 private final JdbcTemplate db;private final TransactionTemplate tx;private final IOrderRepository orders;private final IChannelClosing channel;private final ISettlementRepository settlement;private final ObjectMapper json=new ObjectMapper();
 public PaymentClosingRepository(DataSource ds,TransactionTemplate tx,IOrderRepository orders,IChannelClosing channel,ISettlementRepository settlement){db=new JdbcTemplate(ds);this.tx=tx;this.orders=orders;this.channel=channel;this.settlement=settlement;}
 private long now(){return db.queryForObject("SELECT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED)",Long.class);}
 private Map<String,Object> first(String sql,Object...args){var rows=db.queryForList(sql,args);return rows.isEmpty()?null:rows.getFirst();}
 private String encode(Object x){try{return json.writeValueAsString(x);}catch(Exception e){throw new IllegalStateException("Close serialization failed",e);}}
 private <T>T decode(byte[] x,Class<T> type){try{return json.readValue(x,type);}catch(Exception e){throw new IllegalArgumentException("Close proof invalid",e);}}
 private String hash(byte[] x){return OrderService.hash(new String(x,StandardCharsets.UTF_8));}
 private List<CloseAttempt> attempts(String payment){return db.query("SELECT attempt_id,attempt_no,request_hash FROM b_payment_attempt WHERE payment_id=? ORDER BY attempt_no FOR UPDATE",(rs,i)->new CloseAttempt(rs.getString(1),rs.getInt(2),rs.getString(3)),payment);}
 private Map<String,Object> payment(String order){return first("SELECT * FROM b_payment WHERE order_id=? FOR UPDATE",order);}
 private java.util.function.Predicate<String> reconciliationPolicy=id->false;
 public void enableReconciliation(java.util.function.Predicate<String> policy){reconciliationPolicy=policy;}
 public boolean eligible(MarketOrder o){var p=first("SELECT funds_state,gate,review_required FROM b_payment WHERE order_id=?",o.orderId());return (!o.reviewRequired()||reconciliationPolicy.test(o.orderId()))&&Set.of("WAITING_PAYMENT","PAYMENT_PROCESSING","CLOSING").contains(o.businessStatus())&&p!=null&&(!Boolean.TRUE.equals(p.get("review_required"))||reconciliationPolicy.test(o.orderId()))&&!"SUCCEEDED".equals(p.get("funds_state"))&&Set.of("OPEN","CLOSING").contains(p.get("gate"));}
 public boolean begin(MarketOrder o,String reason,String code,long n){
  if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("Mclose requires market transaction");
  var p=payment(o.orderId());if(!eligible(o)||p==null)return false;var all=attempts(p.get("payment_id").toString());if(all.isEmpty())throw new IllegalStateException("Missing close coverage");
  var row=first("SELECT close_request FROM b_market_order WHERE order_id=?",o.orderId());if(row.get("close_request")!=null)throw new IllegalStateException("Frozen close cannot change");
  if(p.get("channel_close_id")==null){var c=o.confirmation();var request=new PaymentClose(p.get("payment_id").toString(),UUID.randomUUID().toString(),reason,o.orderId(),c.userId(),c.source(),c.channel(),p.get("snapshot_hash").toString(),p.get("amount").toString(),"CNY",((Number)p.get("reserved_at_ms")).longValue(),((Number)p.get("payment_deadline_ms")).longValue(),all);String raw=encode(request);
   db.update("UPDATE b_payment SET gate='CLOSING',channel_close_id=?,channel_close_request=?,channel_close_request_hash=?,version=version+1,updated_at_ms=? WHERE payment_id=?",request.closeId(),raw.getBytes(StandardCharsets.UTF_8),OrderService.hash(raw),n,request.paymentId());
   db.update("UPDATE b_payment_task SET intent_version=intent_version+1,state='DONE',lease_token=NULL,lease_until_ms=NULL,last_error='PAYMENT_CLOSING' WHERE payment_id=?",request.paymentId());
  }
  db.update("UPDATE b_market_order SET business_status='CLOSING',last_error=?,order_version=order_version+1,updated_at_ms=? WHERE order_id=?",code,n,o.orderId());return true;
 }
 private MarketOrder lock(String id){var loc=first("SELECT user_id,goods_id FROM b_market_order WHERE order_id=?",id);if(loc==null)return null;String user=loc.get("user_id").toString(),goods=loc.get("goods_id").toString();
  db.queryForList("SELECT user_id FROM b_user WHERE user_id=? FOR UPDATE",user);db.queryForList("SELECT goods_id FROM b_product WHERE goods_id=? FOR UPDATE",goods);db.queryForList("SELECT user_id FROM b_purchase_guard WHERE user_id=? AND goods_id=? FOR UPDATE",user,goods);db.queryForList("SELECT goods_id FROM b_inventory_account WHERE goods_id=? FOR UPDATE",goods);db.queryForList("SELECT order_id FROM b_market_order WHERE order_id=? FOR UPDATE",id);db.queryForList("SELECT order_id FROM b_inventory_reservation WHERE order_id=? FOR UPDATE",id);db.queryForList("SELECT order_id FROM b_trade_coordination WHERE order_id=? FOR UPDATE",id);var p=payment(id);if(p!=null)attempts(p.get("payment_id").toString());return orders.byId(user,id);
 }
 private boolean current(TradeLease l){var t=first("SELECT * FROM b_trade_coordination WHERE order_id=?",l.orderId());return t!=null&&!Boolean.TRUE.equals(t.get("paused"))&&"LEASED".equals(t.get("run_state"))&&l.token().equals(t.get("lease_token"))&&l.intent().equals(t.get("intent"))&&l.intentVersion()==((Number)t.get("intent_version")).longValue()&&((Number)t.get("lease_until_ms")).longValue()>now();}
 private PaymentClose request(Map<String,Object> p){byte[] raw=(byte[])p.get("channel_close_request");if(raw==null||!hash(raw).equals(p.get("channel_close_request_hash")))throw new IllegalArgumentException("Close request hash mismatch");var r=decode(raw,PaymentClose.class);if(!r.paymentId().equals(p.get("payment_id"))||!r.closeId().equals(p.get("channel_close_id"))||!r.orderId().equals(p.get("order_id"))||!r.userId().equals(p.get("user_id"))||!r.snapshotHash().equals(p.get("snapshot_hash"))||!r.amount().equals(p.get("amount").toString())||!r.currency().equals(p.get("currency"))||r.reservedAt()!=((Number)p.get("reserved_at_ms")).longValue()||r.deadline()!=((Number)p.get("payment_deadline_ms")).longValue()||!r.attempts().equals(attempts(r.paymentId())))throw new IllegalArgumentException("Close attempt coverage changed");return r;}
 public boolean prepare(TradeLease lease){
  ChannelClosure observed=null;
  try{
  PaymentClose r=tx.execute(s->{var o=lock(lease.orderId());if(o==null||!current(lease)||!"CLOSING".equals(o.businessStatus())||"NEVER_OPENED".equals(o.paymentExposure()))return null;var p=payment(o.orderId());return p==null||p.get("channel_close_id")==null?null:request(p);});
  if(r==null)return true;
   var result=channel.queryClose(r);if(result==null)result=channel.closeRoot(r);observed=result;
   if("PAID".equals(result.gate())){if(!r.equals(result.request())||result.paid()==null||!r.paymentId().equals(result.paid().channel().paymentId())||!"SUCCEEDED".equals(result.paid().channel().state())||!"PAID".equals(result.paid().gate()))throw new IllegalArgumentException("Invalid paid close result");settlement.observe(result.paid());return false;}
   var proof=result;return Boolean.TRUE.equals(tx.execute(s->{var o=lock(lease.orderId());if(o==null||!current(lease)||!"CLOSING".equals(o.businessStatus()))return false;var p=payment(o.orderId());if("SUCCEEDED".equals(p.get("funds_state")))return false;var expected=request(p);proof.validateUnpaid(expected,now());long n=now();String raw=encode(proof),digest=OrderService.hash(raw);var row=first("SELECT close_request,close_reason FROM b_market_order WHERE order_id=?",o.orderId());
    if(p.get("channel_close_proof")!=null){if(!digest.equals(p.get("channel_close_proof_hash"))||!proven(o))throw new IllegalArgumentException("Frozen close proof conflict");return true;}
    if(row.get("close_request")!=null)throw new IllegalArgumentException("Existing A declaration without proof");
    db.update("UPDATE b_payment SET gate='CLOSED_UNPAID',funds_state='UNPAID',channel_close_proof=?,channel_close_proof_hash=?,covered_attempt_no=?,channel_closed_at_ms=?,close_verified_at_ms=?,version=version+1,updated_at_ms=? WHERE payment_id=?",raw.getBytes(StandardCharsets.UTF_8),digest,expected.attempts().getLast().attemptNo(),proof.closedAt(),n,n,r.paymentId());
    for(var a:proof.attempts())db.update("UPDATE b_payment_attempt SET state=?,channel_transaction_id=?,last_error=NULL,version=version+1,updated_at_ms=? WHERE payment_id=? AND attempt_id=? AND state<>'SUCCEEDED'",a.state(),a.transactionId(),n,r.paymentId(),a.attemptId());
    var c=o.confirmation();var a=new TreeMap<String,Object>();a.put("source",c.source());a.put("channel",c.channel());a.put("userId",c.userId());a.put("outTradeNo",o.orderId());a.put("closeId",r.closeId());a.put("reason",expected.reason());a.put("paymentDisposition","CLOSED_UNPAID");a.put("verifiedAt",PaymentService.time(n));String frozen=encode(a);
    db.update("UPDATE b_market_order SET close_request=?,close_request_hash=?,close_reason=?,channel_close_proof_hash=?,order_version=order_version+1,updated_at_ms=? WHERE order_id=? AND close_request IS NULL",frozen,OrderService.hash(frozen),expected.reason(),digest,n,o.orderId());return true;
   }));
  }catch(Exception unknown){boolean conflict=unknown instanceof IllegalArgumentException||unknown instanceof cn.zj.zjmarket.types.exception.OrderFailure f&&f.status()==409;byte[] bad=observed==null?new byte[0]:encode(observed).getBytes(StandardCharsets.UTF_8);tx.executeWithoutResult(s->{var o=lock(lease.orderId());if(o==null||!current(lease)||!"CLOSING".equals(o.businessStatus()))return;var p=payment(o.orderId());if(p==null||"SUCCEEDED".equals(p.get("funds_state")))return;if(conflict){settlement.quarantine(p.get("channel_close_id").toString(),"SIMULATED_CHANNEL","CLOSE_ROOT",null,null,bad,"CHANNEL_CLOSE_CONFLICT");db.update("UPDATE b_payment SET review_required=TRUE,last_error='CHANNEL_CLOSE_CONFLICT',version=version+1 WHERE payment_id=?",p.get("payment_id"));db.update("UPDATE b_market_order SET review_required=TRUE,last_error='CHANNEL_CLOSE_CONFLICT',order_version=order_version+1 WHERE order_id=?",o.orderId());db.update("UPDATE b_trade_coordination SET run_state='REVIEW_REQUIRED',lease_token=NULL,lease_until_ms=NULL,alerted=TRUE,last_error='CHANNEL_CLOSE_CONFLICT',task_version=task_version+1,intent_version=intent_version+1 WHERE order_id=?",o.orderId());return;}
    var t=first("SELECT failure_count FROM b_trade_coordination WHERE order_id=?",o.orderId());long fail=((Number)t.get("failure_count")).longValue()+1,n=now();if(fail==5)TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){org.slf4j.LoggerFactory.getLogger(PaymentClosingRepository.class).warn("Channel closing requires attention; automatic recovery continues: orderId={}",lease.orderId());}});long delay=Math.min(30000L,2000L*(1L<<Math.min(4,fail-1)))+java.util.concurrent.ThreadLocalRandom.current().nextLong(251);
    db.update("UPDATE b_trade_coordination SET intent='CLOSE',intent_version=intent_version+1,task_version=task_version+1,run_state='READY',lease_token=NULL,lease_until_ms=NULL,failure_count=?,alerted=alerted OR ?>=5,next_attempt_ms=?,last_error='CHANNEL_CLOSE_UNKNOWN' WHERE order_id=?",fail,fail,n+delay,o.orderId());db.update("UPDATE b_market_order SET last_error='CHANNEL_CLOSE_UNKNOWN',updated_at_ms=? WHERE order_id=?",n,o.orderId());});return false;}
 }
 public boolean proven(MarketOrder o){try{var p=payment(o.orderId());if(p==null||!"CLOSED_UNPAID".equals(p.get("gate"))||"SUCCEEDED".equals(p.get("funds_state")))return false;var r=request(p);byte[] raw=(byte[])p.get("channel_close_proof");if(raw==null||!hash(raw).equals(p.get("channel_close_proof_hash")))return false;var proof=decode(raw,ChannelClosure.class);long verified=((Number)p.get("close_verified_at_ms")).longValue();proof.validateUnpaid(r,verified);var row=first("SELECT channel_close_proof_hash,CAST(close_request AS CHAR) AS close_request FROM b_market_order WHERE order_id=?",o.orderId());var declaration=json.readTree(row.get("close_request").toString());if(!r.closeId().equals(declaration.path("closeId").asText())||!"CLOSED_UNPAID".equals(declaration.path("paymentDisposition").asText())||!PaymentService.time(verified).equals(declaration.path("verifiedAt").asText()))return false;return hash(raw).equals(row.get("channel_close_proof_hash"))&&proof.closedAt().equals(((Number)p.get("channel_closed_at_ms")).longValue())&&((Number)p.get("covered_attempt_no")).intValue()==r.attempts().getLast().attemptNo();}catch(Exception invalid){return false;}}
}
